<template>
  <section class="page">
    <header><div><h2>资产与预防性保养</h2><p>维护资产二维码、保养计划、库存变动流水和后勤安全事件。</p></div></header>
    <el-tabs v-model="tab">
      <el-tab-pane label="资产台账" name="assets">
        <div class="actions"><el-input v-model="qrToken" placeholder="输入二维码令牌定位资产" clearable style="width:300px" /><el-button @click="scanQr">查询二维码</el-button><el-button type="primary" @click="assetDialog=true">新增资产</el-button></div>
        <el-table :data="assets" border><el-table-column prop="assetCode" label="资产编码" width="150" /><el-table-column prop="assetName" label="资产名称" min-width="180" /><el-table-column prop="category" label="分类" width="130" /><el-table-column prop="serialNumber" label="序列号" width="160" /><el-table-column prop="location" label="位置" min-width="180" /><el-table-column prop="qrToken" label="二维码令牌" min-width="260" /><el-table-column prop="status" label="状态" width="120" /><el-table-column prop="nextMaintenanceDate" label="下次保养" width="120" /></el-table>
      </el-tab-pane>
      <el-tab-pane label="预防性保养" name="plans">
        <div class="actions"><el-button type="primary" :disabled="assets.length===0" @click="planDialog=true">新增保养计划</el-button></div>
        <el-table :data="plans" border><el-table-column prop="planName" label="计划名称" min-width="180" /><el-table-column label="资产" min-width="180"><template #default="scope">{{ assetName(scope.row.assetId) }}</template></el-table-column><el-table-column prop="intervalDays" label="周期（天）" width="110" /><el-table-column prop="nextDueDate" label="下次到期" width="120" /><el-table-column prop="assignedUsername" label="负责人" width="140" /><el-table-column prop="checklist" label="检查清单" min-width="220" /><el-table-column prop="status" label="状态" width="100" /><el-table-column label="操作" width="100"><template #default="scope"><el-button v-if="['ACTIVE','OVERDUE'].includes(scope.row.status)" link type="success" @click="completePlan(scope.row)">完成保养</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="库存流水" name="inventory">
        <div class="actions"><el-button type="primary" @click="inventoryDialog=true">登记库存变动</el-button></div>
        <el-table :data="transactions" border><el-table-column label="物料" min-width="210"><template #default="scope">{{ materialName(scope.row.materialId) }}</template></el-table-column><el-table-column prop="transactionType" label="类型" width="100" /><el-table-column prop="quantity" label="变动数量" width="110" /><el-table-column prop="beforeQuantity" label="变动前" width="100" /><el-table-column prop="afterQuantity" label="变动后" width="100" /><el-table-column prop="reason" label="原因" min-width="220" /><el-table-column prop="operatorUsername" label="操作人" width="140" /><el-table-column label="时间" width="180"><template #default="scope">{{ formatDateTime(scope.row.createTime) }}</template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="安全事件" name="incidents">
        <div class="actions"><el-button type="danger" @click="incidentDialog=true">上报安全事件</el-button></div>
        <el-table :data="incidents" border><el-table-column label="发生时间" width="180"><template #default="scope">{{ formatDateTime(scope.row.occurredAt) }}</template></el-table-column><el-table-column prop="severity" label="等级" width="100" /><el-table-column label="关联资产" min-width="200"><template #default="scope">{{ assetName(scope.row.assetId) }}</template></el-table-column><el-table-column prop="description" label="事件描述" min-width="220" /><el-table-column prop="emergencyAction" label="应急处置" min-width="220" /><el-table-column prop="status" label="状态" width="110" /><el-table-column label="操作" width="90"><template #default="scope"><el-button v-if="scope.row.status!=='CLOSED'" link type="success" @click="closeIncident(scope.row)">结案</el-button></template></el-table-column></el-table>
      </el-tab-pane>
    </el-tabs>

    <el-dialog v-model="assetDialog" title="新增资产" width="620px"><el-form label-width="100px"><el-form-item label="资产编码"><el-input v-model="assetForm.assetCode" /></el-form-item><el-form-item label="资产名称"><el-input v-model="assetForm.assetName" /></el-form-item><el-form-item label="分类"><el-input v-model="assetForm.category" /></el-form-item><el-form-item label="序列号"><el-input v-model="assetForm.serialNumber" /></el-form-item><el-form-item label="位置"><el-input v-model="assetForm.location" /></el-form-item><el-form-item label="购置日期"><el-date-picker v-model="assetForm.purchaseDate" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="质保到期"><el-date-picker v-model="assetForm.warrantyExpiry" value-format="YYYY-MM-DD" /></el-form-item></el-form><template #footer><el-button @click="assetDialog=false">取消</el-button><el-button type="primary" @click="saveAsset">保存</el-button></template></el-dialog>
    <el-dialog v-model="planDialog" title="新增预防性保养计划" width="620px"><el-form label-width="110px"><el-form-item label="资产"><el-select v-model="planForm.assetId" filterable style="width:100%"><el-option v-for="item in assets" :key="item.id" :label="`${item.assetName}（${item.assetCode}）`" :value="item.id" /></el-select></el-form-item><el-form-item label="计划名称"><el-input v-model="planForm.planName" /></el-form-item><el-form-item label="周期天数"><el-input-number v-model="planForm.intervalDays" :min="1" /></el-form-item><el-form-item label="首次到期"><el-date-picker v-model="planForm.nextDueDate" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="负责人账号"><el-input v-model="planForm.assignedUsername" /></el-form-item><el-form-item label="检查清单"><el-input v-model="planForm.checklist" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="planDialog=false">取消</el-button><el-button type="primary" @click="savePlan">保存</el-button></template></el-dialog>
    <el-dialog v-model="inventoryDialog" title="登记库存变动" width="620px"><el-form label-width="110px"><el-form-item label="物料"><el-select v-model="inventoryForm.materialId" filterable style="width:100%"><el-option v-for="item in materials" :key="item.id" :label="`${item.materialName}（${item.materialCode}）`" :value="item.id" /></el-select></el-form-item><el-form-item label="变动类型"><el-select v-model="inventoryForm.transactionType"><el-option label="入库" value="IN" /><el-option label="出库" value="OUT" /><el-option label="退库" value="RETURN" /><el-option label="盘点调整" value="ADJUST" /></el-select></el-form-item><el-form-item label="数量"><el-input-number v-model="inventoryForm.quantity" :precision="3" /></el-form-item><el-form-item label="原因"><el-input v-model="inventoryForm.reason" /></el-form-item></el-form><template #footer><el-button @click="inventoryDialog=false">取消</el-button><el-button type="primary" @click="saveInventory">确认登记</el-button></template></el-dialog>
    <el-dialog v-model="incidentDialog" title="上报后勤安全事件" width="640px"><el-form label-width="100px"><el-form-item label="关联资产"><el-select v-model="incidentForm.assetId" clearable filterable style="width:100%"><el-option v-for="item in assets" :key="item.id" :label="`${item.assetName}（${item.assetCode}）`" :value="item.id" /></el-select></el-form-item><el-form-item label="事件等级"><el-select v-model="incidentForm.severity"><el-option label="低" value="LOW" /><el-option label="中" value="MEDIUM" /><el-option label="高" value="HIGH" /><el-option label="重大" value="CRITICAL" /></el-select></el-form-item><el-form-item label="事件描述"><el-input v-model="incidentForm.description" type="textarea" /></el-form-item><el-form-item label="应急处置"><el-input v-model="incidentForm.emergencyAction" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="incidentDialog=false">取消</el-button><el-button type="danger" @click="saveIncident">确认上报</el-button></template></el-dialog>
  </section>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { adjustInventory, closeFacilitySafetyIncident, completePreventivePlan, createFacilityAsset, createPreventivePlan, facilityAssetByQr, facilityAssets, facilitySafetyIncidents, inventoryTransactions, materials as loadMaterials, preventivePlans, reportFacilitySafetyIncident } from '../api'

const unwrap = result => result?.data?.content || result?.data || []
const message = error => error?.response?.data?.msg || error?.message || '操作失败'
const tab = ref('assets'); const qrToken = ref(''); const assets = ref([]); const plans = ref([]); const transactions = ref([]); const incidents = ref([]); const materials = ref([])
const assetDialog = ref(false); const planDialog = ref(false); const inventoryDialog = ref(false); const incidentDialog = ref(false)
const assetForm = reactive({ assetCode: '', assetName: '', category: '', serialNumber: '', organizationId: '', location: '', purchaseDate: '', warrantyExpiry: '', status: 'IN_SERVICE' })
const planForm = reactive({ assetId: '', planName: '', intervalDays: 30, nextDueDate: '', assignedUsername: '', checklist: '' })
const inventoryForm = reactive({ materialId: '', transactionType: 'IN', quantity: 1, reason: '' })
const incidentForm = reactive({ repairOrderId: '', assetId: '', severity: 'LOW', description: '', emergencyAction: '' })
const assetName = id => assets.value.find(item => item.id === id)?.assetName || id
const materialName = id => { const item = materials.value.find(value => value.id === id); return item ? `${item.materialName}（${item.materialCode}）` : '物料已归档' }
const formatDateTime = value => value ? String(value).replace('T', ' ').replace(/\.\d+/, '').replace(/Z$/, '') : '-'
const reload = async () => { try { [assets.value, plans.value, transactions.value, incidents.value, materials.value] = await Promise.all([facilityAssets().then(unwrap), preventivePlans().then(unwrap), inventoryTransactions().then(unwrap), facilitySafetyIncidents().then(unwrap), loadMaterials({ page: 0, size: 500 }).then(unwrap)]) } catch (error) { ElMessage.error(message(error)) } }
const scanQr = async () => { if (!qrToken.value) return ElMessage.warning('请输入二维码令牌'); try { const result = await facilityAssetByQr(qrToken.value); const asset = result.data; ElMessage.success(`已定位：${asset.assetName} / ${asset.location}`) } catch (error) { ElMessage.error(message(error)) } }
const saveAsset = async () => { try { await createFacilityAsset(assetForm); assetDialog.value=false; ElMessage.success('资产已建档并生成二维码令牌'); await reload() } catch (error) { ElMessage.error(message(error)) } }
const savePlan = async () => { try { await createPreventivePlan(planForm); planDialog.value=false; ElMessage.success('预防性保养计划已创建'); await reload() } catch (error) { ElMessage.error(message(error)) } }
const completePlan = async row => { try { const note = (await ElMessageBox.prompt('填写本次保养完成说明', '完成保养')).value; await completePreventivePlan(row.id, note); ElMessage.success('保养已完成并滚动下次到期日'); await reload() } catch (error) { if (!['cancel','close'].includes(error)) ElMessage.error(message(error)) } }
const saveInventory = async () => { try { await adjustInventory({ ...inventoryForm, idempotencyKey: `MANUAL:${Date.now()}` }); inventoryDialog.value=false; ElMessage.success('库存流水已登记'); await reload() } catch (error) { ElMessage.error(message(error)) } }
const saveIncident = async () => { try { await reportFacilitySafetyIncident(incidentForm); incidentDialog.value=false; ElMessage.success('后勤安全事件已上报'); await reload() } catch (error) { ElMessage.error(message(error)) } }
const closeIncident = async row => { try { const note = (await ElMessageBox.prompt('填写调查与结案说明', '安全事件结案')).value; await closeFacilitySafetyIncident(row.id, note); ElMessage.success('安全事件已结案'); await reload() } catch (error) { if (!['cancel','close'].includes(error)) ElMessage.error(message(error)) } }
onMounted(reload)
</script>

<style scoped>
.page { padding: 24px; } header { margin-bottom: 18px; } h2 { margin: 0 0 6px; } p { margin: 0; color: #84909a; } .actions { display: flex; justify-content: flex-end; gap: 10px; margin-bottom: 10px; }
</style>
